def draw_char(display, ch, x, y, color, scale=1):
    data, w, h = CHARS[ch]
    out_w = w * scale
    out_h = h * scale
    buf = bytearray(out_w * out_h * 2)
    color_bytes = color.to_bytes(2, "big")
    row_bytes = w // 8

    for sy in range(h):
        row_base = sy * row_bytes
        for sx in range(w):
            data_index = row_base + sx // 8
            if data_index >= len(data):
                continue
            byte_value = data[data_index]
            bit_mask = 0x80 >> (sx % 8)
            if byte_value & bit_mask:
                for dy in range(scale):
                    for dx in range(scale):
                        out_x = sx * scale + dx
                        out_y = sy * scale + dy
                        offset = (out_y * out_w + out_x) * 2
                        buf[offset] = color_bytes[0]
                        buf[offset + 1] = color_bytes[1]

    display._window_and_data(x, y, x + out_w - 1, y + out_h - 1, buf)


def draw_title(display, x, y, color):
    for row, line in enumerate(TITLE_LINES):
        for col, ch in enumerate(line):
            draw_char(display, ch, x + col * FONT_W, y + row * (FONT_H + TITLE_GAP_Y), color)
